import React, { useEffect, useState } from 'react';
import { getAssociatedFranchises, createUserExamData } from '../services/api'; // Import your API functions

const AssociatedFranchises = () => {
  const [franchises, setFranchises] = useState([]);
  const [examData, setExamData] = useState({
    franchiseId: '',
    examName: '',
    examDate: '',
  });
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState('');

  // Fetch associated franchises when the component mounts
  useEffect(() => {
    const fetchFranchises = async () => {
      try {
        const data = await getAssociatedFranchises();
        setFranchises(data);
      } catch (error) {
        setError('Failed to fetch associated franchises.');
      }
    };
    
    fetchFranchises();
  }, []);

  // Handle exam data form change
  const handleExamDataChange = (e) => {
    setExamData({
      ...examData,
      [e.target.name]: e.target.value,
    });
  };

  // Handle form submission to create exam data
  const handleCreateExamData = async (e) => {
    e.preventDefault();
    try {
      const response = await createUserExamData(examData);
      setSuccess('Exam data created successfully!');
      setExamData({ franchiseId: '', examName: '', examDate: '' }); // Reset the form
    } catch (error) {
      setError('Failed to create exam data.');
    }
  };

  return (
    <div>
      <h2>Associated Franchises</h2>

      {/* Show list of associated franchises */}
      {franchises.length > 0 ? (
        <ul>
          {franchises.map((franchise) => (
            <li key={franchise.id}>{franchise.name}</li>
          ))}
        </ul>
      ) : (
        <p>No associated franchises found.</p>
      )}

      {/* Form for creating exam data */}
      <h3>Create Exam Data</h3>
      <form onSubmit={handleCreateExamData}>
        <div>
          <label htmlFor="franchiseId">Franchise</label>
          <select
            name="franchiseId"
            value={examData.franchiseId}
            onChange={handleExamDataChange}
            required
          >
            <option value="">Select a Franchise</option>
            {franchises.map((franchise) => (
              <option key={franchise._id} value={franchise._id}>
                {franchise.name}
              </option>
            ))}
          </select>
        </div>
        
        <div>
          <label htmlFor="examName">Exam Name</label>
          <input
            type="text"
            name="examName"
            value={examData.examName}
            onChange={handleExamDataChange}
            required
          />
        </div>

        <div>
          <label htmlFor="examDate">Exam Date</label>
          <input
            type="date"
            name="examDate"
            value={examData.examDate}
            onChange={handleExamDataChange}
            required
          />
        </div>

        <button type="submit">Create Exam Data</button>
      </form>

      {/* Display success or error messages */}
      {error && <p style={{ color: 'red' }}>{error}</p>}
      {success && <p style={{ color: 'green' }}>{success}</p>}
    </div>
  );
};

export default AssociatedFranchises;
